from pydantic import BaseModel, ConfigDict, Field

from app.models.course import DifficultyLevel
from app.models.quiz import QuestionType


class AIGeneratedQuestion(BaseModel):
    """Schema for a single question generated by Gemini structured output."""

    model_config = ConfigDict(extra="ignore")

    question: str = Field(..., description="The question prompt")
    question_type: QuestionType = Field(default=QuestionType.MCQ, description="MCQ or TRUE_FALSE")
    options: list[str] | None = Field(
        default=None,
        description="List of 3 to 5 options for MCQ; ['True', 'False'] for TRUE_FALSE",
    )
    correct_answer: str = Field(..., description="The exact correct option string")
    explanation: str = Field(..., description="Educational explanation for why the answer is correct")
    topic_tag: str | None = Field(default=None, description="Subtopic tag or concept name")


class AIGeneratedQuizPayload(BaseModel):
    """Schema for Gemini structured output representing a full generated quiz."""

    model_config = ConfigDict(extra="ignore")

    title: str = Field(..., description="Engaging quiz title")
    topic: str = Field(..., description="Core subject topic")
    difficulty: DifficultyLevel = Field(..., description="Assessed difficulty level")
    questions: list[AIGeneratedQuestion] = Field(..., min_length=1)


class AIQuizGenerateRequest(BaseModel):
    """User request payload for generating an adaptive AI quiz."""

    model_config = ConfigDict(extra="forbid")

    topic: str = Field(..., min_length=2, max_length=150, description="Topic to generate quiz for")
    difficulty: DifficultyLevel = Field(
        default=DifficultyLevel.INTERMEDIATE,
        description="Target difficulty level",
    )
    num_questions: int = Field(
        default=5,
        ge=1,
        le=20,
        description="Number of questions to generate (1-20)",
    )
    lesson_id: str | None = Field(
        default=None,
        description="Optional lesson ID to ground quiz questions directly from lesson content",
    )
    question_types: list[QuestionType] | None = Field(
        default=None,
        description="Allowed question types (e.g. ['mcq', 'true_false'])",
    )
    custom_instructions: str | None = Field(
        default=None,
        max_length=1000,
        description="Optional custom pedagogical focus or constraint instructions",
    )


class AIEvalResult(BaseModel):
    """Schema for Gemini structured output evaluating a student's answer."""

    model_config = ConfigDict(extra="ignore")

    is_correct: bool = Field(..., description="Whether the student's answer is accurate and correct")
    confidence: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="AI confidence score from 0.0 to 1.0",
    )
    feedback: str = Field(
        ...,
        description="Constructive, pedagogical feedback explaining the verdict and reinforcing learning",
    )


class AIEvaluateAnswerRequest(BaseModel):
    """Request payload to evaluate an answer with AI feedback."""

    model_config = ConfigDict(extra="forbid")

    question_id: str = Field(..., description="The quiz question ID to evaluate against")
    user_answer: str = Field(..., min_length=1, description="Student's submitted answer")


class AIEvaluateAnswerResponse(BaseModel):
    """Response payload containing AI evaluation and feedback."""

    model_config = ConfigDict(from_attributes=True)

    question_id: str
    user_answer: str
    is_correct: bool
    ai_confidence: float
    ai_feedback: str
